function waitingRoomChatLines(lines, now = Date.now()) {
  const output = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.system && /^Match starting in [1-4]…$/.test(line.text)) continue;
    output.push(line);
    if (!line.system || line.text !== "Match starting in 5\u2026") continue;
    const end = lines.slice(i + 1).find((next) => next.system && !/^Match starting in [1-4]…$/.test(next.text))?.at ?? Infinity;
    for (let second = 4; second >= 1; second--) {
      const at = line.at + (5 - second) * 1e3;
      if (at <= now && at < end) output.push({ ...line, at, text: `Match starting in ${second}\u2026` });
    }
  }
  return output.sort((a, b) => a.at - b.at).map((line, index) => ({ ...line, seq: index + 1 }));
}

