function formatTime(frames) {
  if (!Number.isFinite(frames) || frames < 0) return "\u2014";
  const ms = Math.floor(frames);
  return `${Math.floor(ms / 6e4)}:${String(Math.floor(ms / 1e3) % 60).padStart(2, "0")}.${String(ms % 1e3).padStart(3, "0")}`;
}
