      this.#directory.setUser(this.#user?.id ?? null);
      if (previous === (this.#user?.id ?? null) && _event !== "USER_UPDATED") return;
      if (previous !== (this.#user?.id ?? null)) {
        this.#profileName = "";
        this.#rating = null;
      }
      this.#profileError = "";
      const revision = ++this.#revision;
      this.#changed();
